// Generates docs/field-mapping.md from backend/Core.js so the doc can never drift from the code.
const fs = require('fs');
const path = require('path');
const Core = require('../backend/Core.js');

const lines = [
  '# Field mapping: RYD-SO worksheet to application',
  '',
  '_Generated by `npm run gen:docs` from `backend/Core.js`. Do not edit by hand._',
  '',
  'Header row = 2, data starts at row 3. Row 1 holds helper numbers and is ignored.',
  '',
  '| Col | Worksheet header | App key | Type | In the app | Validation (from the sheet) |',
  '|---|---|---|---|---|---|'
];
for (const f of Core.FIELDS) {
  const mode = f.calc ? 'Read-only (formula column)' : 'Editable (unless the cell holds a formula)';
  const rule = f.options ? 'Dropdown: ' + f.options.join(', ') : f.type === 'date' ? 'Date YYYY-MM-DD' : (f.type === 'number' || f.type === 'currency') ? 'Number' : f.type === 'id' ? 'Text, leading zeros kept' : 'Free text';
  lines.push(`| ${f.col} | ${f.label} | \`${f.key}\` | ${f.type} | ${mode} | ${rule}${f.note ? ' — ' + f.note : ''} |`);
}
lines.push('', `| (added) | ${Core.ID_HEADER} | \`id\` | text | hidden stable key | Added once by \`setupApp()\` after the last column |`, '');
fs.writeFileSync(path.join(__dirname, '..', 'docs', 'field-mapping.md'), lines.join('\n'));
console.log('wrote docs/field-mapping.md');
